(function() {
        const curlInput = document.getElementById('curl-input');
        const clearCurlBtn = document.getElementById('clear-curl-btn');
        const codeOutput = document.getElementById('code-output');
        const copyCodeBtn = document.getElementById('copy-code-btn');
        const copyCodeText = document.getElementById('copy-code-text');
        const downloadCodeBtn = document.getElementById('download-code-btn');

        const parsedMethodEl = document.getElementById('parsed-method');
        const parsedUrlEl = document.getElementById('parsed-url');
        const parsedHeadersEl = document.getElementById('parsed-headers');
        const parsedBodyEl = document.getElementById('parsed-body');

        const tabs = {
            fetch: document.getElementById('tab-fetch'),
            axios: document.getElementById('tab-axios'),
            node: document.getElementById('tab-node'),
            python: document.getElementById('tab-python')
        };

        let currentTarget = 'fetch'; // 'fetch', 'axios', 'node', 'python'

        // Tokenizer / Parser for cURL arguments
        function parseCurl(raw) {
            if (!raw || !raw.trim()) {
                return null;
            }

            let cmd = raw.replace(/\\\r?\n/g, ' ').replace(/\\n/g, ' ').trim();
            if (cmd.startsWith('curl ')) {
                cmd = cmd.substring(5).trim();
            }

            const tokens = [];
            let current = '';
            let inSingle = false;
            let inDouble = false;
            let escaped = false;

            for (let i = 0; i < cmd.length; i++) {
                const char = cmd[i];
                if (escaped) {
                    current += char;
                    escaped = false;
                    continue;
                }
                if (char === '\\' && !inSingle) {
                    escaped = true;
                    continue;
                }
                if (char === "'" && !inDouble) {
                    inSingle = !inSingle;
                    continue;
                }
                if (char === '"' && !inSingle) {
                    inDouble = !inDouble;
                    continue;
                }
                if (/\s/.test(char) && !inSingle && !inDouble) {
                    if (current) {
                        tokens.push(current);
                        current = '';
                    }
                } else {
                    current += char;
                }
            }
            if (current) tokens.push(current);

            const result = {
                method: '',
                url: '',
                headers: {},
                data: null,
                auth: null
            };

            for (let i = 0; i < tokens.length; i++) {
                const t = tokens[i];
                if (t === '-X' || t === '--request') {
                    if (i + 1 < tokens.length) {
                        result.method = tokens[++i].toUpperCase();
                    }
                } else if (t === '-H' || t === '--header') {
                    if (i + 1 < tokens.length) {
                        const hStr = tokens[++i];
                        const colonIdx = hStr.indexOf(':');
                        if (colonIdx > -1) {
                            const k = hStr.substring(0, colonIdx).trim();
                            const v = hStr.substring(colonIdx + 1).trim();
                            result.headers[k] = v;
                        }
                    }
                } else if (t === '-d' || t === '--data' || t === '--data-raw' || t === '--data-binary' || t === '--json') {
                    if (i + 1 < tokens.length) {
                        result.data = (result.data ? result.data + '&' : '') + tokens[++i];
                        if (!result.method) result.method = 'POST';
                    }
                } else if (t === '-u' || t === '--user') {
                    if (i + 1 < tokens.length) {
                        result.auth = tokens[++i];
                    }
                } else if (!t.startsWith('-') && !result.url) {
                    result.url = t.replace(/^['"]|['"]$/g, '');
                }
            }

            if (!result.method) {
                result.method = result.data ? 'POST' : 'GET';
            }

            if (result.auth) {
                try {
                    result.headers['Authorization'] = 'Basic ' + btoa(result.auth);
                } catch(e) {}
            }

            return result;
        }

        // Code Generators
        function generateFetchCode(parsed) {
            if (!parsed || !parsed.url) {
                return '// Please provide a valid cURL command with a destination URL.';
            }

            const hasHeaders = Object.keys(parsed.headers).length > 0;
            const hasData = Boolean(parsed.data);

            let bodyCode = '';
            let isJson = false;

            if (hasData) {
                try {
                    const parsedJson = JSON.parse(parsed.data);
                    isJson = true;
                    bodyCode = '        body: JSON.stringify(' + JSON.stringify(parsedJson, null, 4).replace(/\n/g, '\n        ') + ')';
                } catch (e) {
                    bodyCode = '        body: ' + JSON.stringify(parsed.data);
                }
            }

            const headerLines = [];
            for (const [k, v] of Object.entries(parsed.headers)) {
                headerLines.push("            '" + k + "': '" + v + "'");
            }

            let code = 'async function sendRequest() {\n';
            code += "    const url = '" + parsed.url + "';\n";
            code += '    const options = {\n';
            code += "        method: '" + parsed.method + "',\n";

            if (hasHeaders) {
                code += '        headers: {\n' + headerLines.join(',\n') + '\n        }';
            } else if (isJson) {
                code += "        headers: {\n            'Content-Type': 'application/json'\n        }";
            }

            if (hasData) {
                if (hasHeaders || isJson) code += ',\n';
                code += bodyCode + '\n';
            } else if (hasHeaders) {
                code += '\n';
            }

            code += '    };\n\n';
            code += '    try {\n';
            code += '        const response = await fetch(url, options);\n';
            code += '        if (!response.ok) {\n';
            code += '            throw new Error(`HTTP Error: ${response.status} ${response.statusText}`);\n';
            code += '        }\n';
            code += '        const result = await response.json();\n';
            code += "        console.log('Success:', result);\n";
            code += '        return result;\n';
            code += '    } catch (error) {\n';
            code += "        console.error('Request failed:', error);\n";
            code += '    }\n';
            code += '}\n\n';
            code += 'sendRequest();';
            return code;
        }

        function generateAxiosCode(parsed) {
            if (!parsed || !parsed.url) return '// Please enter a cURL command with a destination URL.';

            let dataObj = null;
            if (parsed.data) {
                try {
                    dataObj = JSON.parse(parsed.data);
                } catch(e) {
                    dataObj = parsed.data;
                }
            }

            let code = "import axios from 'axios';\n\n";
            code += 'async function executeRequest() {\n';
            code += '    try {\n';
            code += '        const response = await axios({\n';
            code += "            method: '" + parsed.method.toLowerCase() + "',\n";
            code += "            url: '" + parsed.url + "',\n";

            if (Object.keys(parsed.headers).length > 0) {
                const headerLines = Object.entries(parsed.headers).map(([k,v]) => "                '" + k + "': '" + v + "'").join(',\n');
                code += '            headers: {\n' + headerLines + '\n            },';
            }

            if (dataObj) {
                if (typeof dataObj === 'object') {
                    code += '\n            data: ' + JSON.stringify(dataObj, null, 4).replace(/\n/g, '\n            ') + '\n';
                } else {
                    code += "\n            data: '" + dataObj + "'\n";
                }
            } else {
                code += '\n';
            }

            code += '        });\n\n';
            code += "        console.log('Response:', response.data);\n";
            code += '        return response.data;\n';
            code += '    } catch (error) {\n';
            code += '        if (error.response) {\n';
            code += "            console.error('API Error:', error.response.status, error.response.data);\n";
            code += '        } else {\n';
            code += "            console.error('Network Error:', error.message);\n";
            code += '        }\n';
            code += '    }\n';
            code += '}\n\n';
            code += 'executeRequest();';
            return code;
        }

        function generateNodeCode(parsed) {
            return generateFetchCode(parsed).replace('async function sendRequest() {', '// Node.js 18+ (Native Fetch Supported)\nasync function sendRequest() {');
        }

        function generatePythonCode(parsed) {
            if (!parsed || !parsed.url) return '# Please provide a valid cURL command with a destination URL.';

            let code = 'import requests\nimport json\n\n';
            code += 'url = "' + parsed.url + '"\n\n';

            const hasHeaders = Object.keys(parsed.headers).length > 0;
            if (hasHeaders) {
                code += 'headers = {\n';
                for (const [k, v] of Object.entries(parsed.headers)) {
                    code += '    "' + k + '": "' + v + '",\n';
                }
                code += '}\n\n';
            } else {
                code += 'headers = {}\n\n';
            }

            let isJson = false;
            if (parsed.data) {
                try {
                    const parsedJson = JSON.parse(parsed.data);
                    isJson = true;
                    code += 'payload = ' + JSON.stringify(parsedJson, null, 4) + '\n\n';
                } catch(e) {
                    code += 'payload = """' + parsed.data + '"""\n\n';
                }
            }

            code += 'try:\n';
            let reqLine = '    response = requests.' + parsed.method.toLowerCase() + '(url, headers=headers';
            if (parsed.data) {
                reqLine += isJson ? ', json=payload' : ', data=payload';
            }
            reqLine += ')\n';
            code += reqLine;
            code += '    response.raise_for_status()\n';
            code += '    print("Status:", response.status_code)\n';
            code += '    print("Data:", response.json())\n';
            code += 'except requests.exceptions.RequestException as e:\n';
            code += '    print("HTTP Request Failed:", e)\n';
            return code;
        }

        function parseAndGenerate() {
            const raw = curlInput.value;
            const parsed = parseCurl(raw);

            if (!parsed || !parsed.url) {
                codeOutput.textContent = '// Enter a cURL command in the box above to generate code.';
                parsedMethodEl.textContent = 'GET';
                parsedUrlEl.textContent = 'None specified';
                parsedHeadersEl.innerHTML = '<span class="text-slate-400 italic">None</span>';
                parsedBodyEl.innerHTML = '<span class="text-slate-400 italic">None</span>';
                return;
            }

            // Update Breakdown Panel
            parsedMethodEl.textContent = parsed.method;
            parsedUrlEl.textContent = parsed.url;

            const headerEntries = Object.entries(parsed.headers);
            if (headerEntries.length > 0) {
                parsedHeadersEl.innerHTML = headerEntries.map(([k,v]) => '<div><strong class="text-slate-900">' + k + ':</strong> <span class="text-slate-600">' + v + '</span></div>').join('');
            } else {
                parsedHeadersEl.innerHTML = '<span class="text-slate-400 italic">None specified</span>';
            }

            if (parsed.data) {
                parsedBodyEl.textContent = parsed.data.length > 120 ? parsed.data.substring(0, 120) + '...' : parsed.data;
            } else {
                parsedBodyEl.innerHTML = '<span class="text-slate-400 italic">None</span>';
            }

            // Update Target Code
            let generated = '';
            if (currentTarget === 'fetch') {
                generated = generateFetchCode(parsed);
            } else if (currentTarget === 'axios') {
                generated = generateAxiosCode(parsed);
            } else if (currentTarget === 'node') {
                generated = generateNodeCode(parsed);
            } else if (currentTarget === 'python') {
                generated = generatePythonCode(parsed);
            }
            codeOutput.textContent = generated;
        }

        // Tab selection
        function setTarget(target) {
            currentTarget = target;
            Object.keys(tabs).forEach(k => {
                if (k === target) {
                    tabs[k].className = 'tab-target active text-xs font-bold px-3 py-1.5 rounded-lg bg-white text-slate-900 shadow-sm transition-all';
                } else {
                    tabs[k].className = 'tab-target text-xs font-bold px-3 py-1.5 rounded-lg text-slate-600 hover:text-slate-900 transition-all';
                }
            });
            parseAndGenerate();
        }

        tabs.fetch.addEventListener('click', () => setTarget('fetch'));
        tabs.axios.addEventListener('click', () => setTarget('axios'));
        tabs.node.addEventListener('click', () => setTarget('node'));
        tabs.python.addEventListener('click', () => setTarget('python'));

        curlInput.addEventListener('input', parseAndGenerate);
        clearCurlBtn.addEventListener('click', () => {
            curlInput.value = '';
            parseAndGenerate();
            curlInput.focus();
        });

        // Copy Code button
        copyCodeBtn.addEventListener('click', () => {
            const text = codeOutput.textContent;
            if (!text) return;
            navigator.clipboard.writeText(text).then(() => {
                copyCodeText.textContent = 'Copied!';
                copyCodeBtn.classList.add('bg-emerald-600');
                setTimeout(() => {
                    copyCodeText.textContent = 'Copy Code';
                    copyCodeBtn.classList.remove('bg-emerald-600');
                }, 2000);
            });
        });

        // Download Code Button
        downloadCodeBtn.addEventListener('click', () => {
            const text = codeOutput.textContent;
            if (!text) return;
            const ext = currentTarget === 'python' ? 'py' : 'js';
            const blob = new Blob([text], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'api_request.' + ext;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        });

        // Presets
        document.getElementById('preset-post-json').addEventListener('click', () => {
            curlInput.value = 'curl -X POST https://api.example.com/v1/users \\\n  -H \'Content-Type: application/json\' \\\n  -H \'Authorization: Bearer secret_token_abc123\' \\\n  -d \'{"name": "Jane Doe", "email": "jane@example.com", "role": "engineer"}\'';
            parseAndGenerate();
        });

        document.getElementById('preset-auth-bearer').addEventListener('click', () => {
            curlInput.value = 'curl https://api.github.com/user/repos \\\n  -H \'Accept: application/vnd.github+json\' \\\n  -H \'Authorization: Bearer ghp_token9876543210\' \\\n  -H \'X-GitHub-Api-Version: 2022-11-28\'';
            parseAndGenerate();
        });

        document.getElementById('preset-form-data').addEventListener('click', () => {
            curlInput.value = 'curl -X POST https://auth.example.com/oauth/token \\\n  -H \'Content-Type: application/x-www-form-urlencoded\' \\\n  -d \'grant_type=client_credentials&client_id=my_client&client_secret=my_secret\'';
            parseAndGenerate();
        });

        // Initial default load
        document.getElementById('preset-post-json').click();
    })();
